INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3145123, 439384, 3102, '<td valign="top">Great movie, and a great replication of that scene!  I''m sure I won''t be the only person here to note that you apparently have a little too much spare time :) - 10</td>', 'Great movie, and a great replication of that scene!  I''m sure I won''t be the only person here to note that you apparently have a little too much spare time :) - 10', '2006-12-23 18:25:55.000000', NULL, 1),
(3145124, 439873, 3102, '<td valign="top">Nicely done!  Definitely a top pick of mine this time.  I like how you shot it on a plain background... most people would probably leave a lot of distracting elements in a shot like this.</td>', 'Nicely done!  Definitely a top pick of mine this time.  I like how you shot it on a plain background... most people would probably leave a lot of distracting elements in a shot like this.', '2006-12-23 18:26:45.000000', NULL, 1),
(3145129, 439478, 3102, '<td valign="top">Seems a little shoe-horned into the challenge as it''s not really strong on the topic.  But as it is, it''s rather dreadfully out of focus.</td>', 'Seems a little shoe-horned into the challenge as it''s not really strong on the topic.  But as it is, it''s rather dreadfully out of focus.', '2006-12-23 18:28:16.000000', NULL, 1),
(3145133, 439881, 3102, '<td valign="top">A decent enough idea, but I''m afraid the execution is rather weak.  The sizing of the shot is too small, lighting a bit too harsh, and the pixelation of the background is a bit distracting.</td>', 'A decent enough idea, but I''m afraid the execution is rather weak.  The sizing of the shot is too small, lighting a bit too harsh, and the pixelation of the background is a bit distracting.', '2006-12-23 18:30:18.000000', NULL, 1),
(3145137, 439771, 3102, '<td valign="top">Honestly, it''s just not appealing.  There''s no real focal point to look at, and without the title, I wouldn''t have known what this was.  It''s also sized way below the allowable dimensions.  I''m afraid it just has a look as though it was taken with a cell phone camera, or something like that.</td>', 'Honestly, it''s just not appealing.  There''s no real focal point to look at, and without the title, I wouldn''t have known what this was.  It''s also sized way below the allowable dimensions.  I''m afraid it just has a look as though it was taken with a cell phone camera, or something like that.', '2006-12-23 18:32:31.000000', NULL, 1),
(3145144, 439103, 3102, '<td valign="top">Nicely done!  Probably my second-favorite one of this type.  This seems just a tad bit contrasty for my taste.  Still a 9, though :)</td>', 'Nicely done!  Probably my second-favorite one of this type.  This seems just a tad bit contrasty for my taste.  Still a 9, though :)', '2006-12-23 18:37:16.000000', NULL, 1),
(3145293, 439468, 24528, '<td valign="top">Not sure I am feeling it..Sorry</td>', 'Not sure I am feeling it..Sorry', '2006-12-23 20:11:48.000000', NULL, 1),
(3145356, 439700, 70328, '<td valign="top">Stunning. Love the ambiguous background and reflections.</td>', 'Stunning. Love the ambiguous background and reflections.', '2006-12-23 20:57:45.000000', NULL, 1),
(3145808, 439468, 13688, '<td valign="top">Sticky how? Sticky what?</td>', 'Sticky how? Sticky what?', '2006-12-24 02:22:44.000000', NULL, 1),
(3145810, 439817, 68956, '<td valign="top">Good idea!</td>', 'Good idea!', '2006-12-24 02:28:16.000000', NULL, 1),
(3145811, 438637, 68956, '<td valign="top">Works well with the title!</td>', 'Works well with the title!', '2006-12-24 02:29:05.000000', NULL, 1),
