(3145817, 439705, 68956, '<td valign="top">Maybe better to focus on the gum, rather than the logo.</td>', 'Maybe better to focus on the gum, rather than the logo.', '2006-12-24 02:33:55.000000', NULL, 1),
(3145818, 439237, 68956, '<td valign="top">Good</td>', 'Good', '2006-12-24 02:34:10.000000', NULL, 1),
(3145819, 439548, 68956, '<td valign="top">Well caught!</td>', 'Well caught!', '2006-12-24 02:35:16.000000', NULL, 1),
(3145972, 439850, 35602, '<td valign="top">I found the subject to be uninteresting photographically.  Also when doing such a close-up, you need to be sure that the image is tack sharp, which this one isn''t.  Your exposure is fine, but the angle also seems a bit unattractive.</td>', 'I found the subject to be uninteresting photographically.  Also when doing such a close-up, you need to be sure that the image is tack sharp, which this one isn''t.  Your exposure is fine, but the angle also seems a bit unattractive.', '2006-12-24 08:21:30.000000', NULL, 1),
(3145973, 439840, 35602, '<td valign="top">This is soooooooo gross, but what an impact.  Immediate reaction, oh yuk, go to the next picture quick.  7</td>', 'This is soooooooo gross, but what an impact.  Immediate reaction, oh yuk, go to the next picture quick.  7', '2006-12-24 08:22:45.000000', NULL, 1),
(3145974, 439771, 35602, '<td valign="top">Looks extremely unappetizing.  What are the black things?  Overall, not a pleasing composition.</td>', 'Looks extremely unappetizing.  What are the black things?  Overall, not a pleasing composition.', '2006-12-24 08:23:23.000000', NULL, 1),
(3145975, 438983, 35602, '<td valign="top">Needs better focus so you could see the tension of the honey under the flies.  Also detail on flies is very matte.  A bit more shine would have been better.</td>', 'Needs better focus so you could see the tension of the honey under the flies.  Also detail on flies is very matte.  A bit more shine would have been better.', '2006-12-24 08:24:42.000000', NULL, 1),
(3145978, 439005, 35602, '<td valign="top">Nice shot.  Great detail on the farthest right buffalo.</td>', 'Nice shot.  Great detail on the farthest right buffalo.', '2006-12-24 08:26:25.000000', NULL, 1),
(3145979, 439478, 35602, '<td valign="top">Need to be clearer and color seems off, maybe too much orange.  Also, the heavy shadows cover up the depth of detail this image could have had.</td>', 'Need to be clearer and color seems off, maybe too much orange.  Also, the heavy shadows cover up the depth of detail this image could have had.', '2006-12-24 08:27:37.000000', NULL, 1),
(3145982, 439767, 35602, '<td valign="top">Beautiful composition and lighting.  Nice detail.  A bit too much brightness on the intersection above the spoon, but overall you did a great job.</td>', 'Beautiful composition and lighting.  Nice detail.  A bit too much brightness on the intersection above the spoon, but overall you did a great job.', '2006-12-24 08:29:17.000000', NULL, 1),
(3145983, 439572, 35602, '<td valign="top">Too cute.  This is hilarious.  But did you wreck that expensive compact flash disk on the left?  Or was it done in anyway?  I don''t know why, photographically there are a few issues, but the entire image and its creativity have grabbed my eye, and I love the kooky eyes.  10</td>', 'Too cute.  This is hilarious.  But did you wreck that expensive compact flash disk on the left?  Or was it done in anyway?  I don''t know why, photographically there are a few issues, but the entire image and its creativity have grabbed my eye, and I love the kooky eyes.  10', '2006-12-24 08:32:03.000000', NULL, 1),
(3146222, 439260, 66384, '<td valign="top">LOL! and very good image. 9</td>', 'LOL! and very good image. 9', '2006-12-24 12:42:49.000000', NULL, 1),
(3146223, 438547, 66384, '<td valign="top">Original concept and excellent execution. I particularly like the three tone background. 10</td>', 'Original concept and excellent execution. I particularly like the three tone background. 10', '2006-12-24 12:45:00.000000', NULL, 1),
(3146228, 439674, 66384, '<td valign="top">The thorns look to be in sharp focus, but I am bothered by the soft focus on the flowers.</td>', 'The thorns look to be in sharp focus, but I am bothered by the soft focus on the flowers.', '2006-12-24 12:46:35.000000', NULL, 1),
(3146230, 439850, 68685, '<td valign="top">too soft</td>', 'too soft', '2006-12-24 12:48:01.000000', NULL, 1),
(3146231, 439638, 66384, '<td valign="top">Yum. I can taste them with my eyes. I''m heading for the kitchen now. I think you got the DOF exactly right. 9</td>', 'Yum. I can taste them with my eyes. I''m heading for the kitchen now. I think you got the DOF exactly right. 9', '2006-12-24 12:48:16.000000', NULL, 1),
